// saju-kid-grade length: every category must read like a full consultation.
const LENGTH_RULE =
  `각 카테고리는 반드시 길게: 15문장 이상, 공백 포함 700자 이상(한국어 기준 — ` +
  `태국어·영어도 같은 정보량). 실제 간지 글자와 일주 이름(예: 을해일주, 병술일주)을 인용하고, ` +
  `명리 근거(합·충·암합·조후·용신·십신)를 짚으며, 생활 속 구체적 장면과 실용 조언(인테리어, 말버릇, ` +
  `시기 등)까지 담아라. 짧고 두루뭉술한 문장은 금지. ` +
  `문단 구성: 한 덩어리로 쓰지 말고 빈 줄(\\n\\n)로 구분된 2~3개 문단으로 나눠라. ` +
  `분위기에 맞는 이모지(🌊 🔥 🌸 💞 🍀 ✨ 등)를 문단당 0~2개, 과하지 않게 자연스레 섞어라.`;

function chunk<T>(arr: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}

// One generation call for a slice of categories. Chunked + parallel so the
// full 12-13 category long-form report fits serverless time limits.
async function callChunk(
  c: AnthropicLike,
  system: string,
  context: string,
  cats: string[],
  startNo: number,
  lang: Lang
): Promise<Array<{ title: string; body: string }> | null> {
  const prompt =
    context +
    `\n\n이건 전체 리포트 중 일부야. 다음 카테고리들만 작성해줘:\n` +
    cats.map((t, i) => `${startNo + i}. ${t}`).join("\n") +
    `\n\n${LENGTH_RULE}\n\n출력은 반드시 JSON 배열만: [{"title":"...","body":"..."}] — ` +
    `title은 각 카테고리를 감성적인 한 줄 제목으로 (번호 없이), body는 본문. ` +
    `모든 텍스트는 ${LANG_NAME[lang]}(으)로.`;
  try {
    const res = await c.messages.create({
      model: MODEL,
      max_tokens: 3000,
      system: [{ type: "text", text: system, cache_control: { type: "ephemeral" } }],
      messages: [{ role: "user", content: prompt }],
    });
    const text = res.content.find((b) => b.type === "text")?.text ?? "";
    const json = text.slice(text.indexOf("["), text.lastIndexOf("]") + 1);
    const parsed = JSON.parse(json) as Array<{ title: string; body: string }>;
    if (!Array.isArray(parsed) || parsed.length === 0) return null;
    const out = parsed.map((sec) => ({
      title: String(sec.title ?? "").slice(0, 120),
      body: String(sec.body ?? ""),
    }));
    // Reject degenerate output — a rare "placeholder" stub, an empty body, or a
    // section far shorter than the length rule asks for. Returning null lets the
    // caller's retry loop regenerate this part instead of saving junk.
    if (out.some((s) => s.body.trim().length < 120 || s.body.trim() === s.title.trim())) {
      return null;
    }
    return out;
  } catch (err) {
    console.error("report chunk generation failed:", err);
    return null;
  }
}

/**
 * Translate ONE generated section into another language, preserving meaning,
 * length, paragraph breaks, and emoji — so every language shows the same
 * report. Client-orchestrated one call per section (like generation).
 */
export async function translateSection(
  title: string,
  body: string,
  lang: Lang
): Promise<{ title: string; body: string } | null> {
  const c = getClient();
  if (!c) return null;
  const prompt =
    `다음 사주 해석 섹션을 ${LANG_NAME[lang]}(으)로 번역해줘. ` +
    `의미와 정보량, 문단 구분(빈 줄), 이모지를 그대로 유지하고, 간지 한자(예: 丙戌, 乙亥)는 그대로 두되 ` +
    `명리 용어는 ${LANG_NAME[lang]} 독자가 이해할 수 있게 자연스럽게 옮겨라. 요약하거나 줄이지 마라. ` +
    `출력은 반드시 JSON 하나만: {"title":"...","body":"..."}\n\n` +
    `[제목] ${title}\n[본문]\n${body}`;
  try {
    const res = await c.messages.create({
      model: MODEL,
      max_tokens: 3000,
      messages: [{ role: "user", content: prompt }],
    });
    const text = res.content.find((b) => b.type === "text")?.text ?? "";
    const json = text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1);
    const p = JSON.parse(json) as { title: string; body: string };
    if (!p?.title || !p?.body) return null;
    // Reject a degenerate/placeholder translation so the retry loop re-runs it.
    if (String(p.body).trim().length < 120) return null;
    return { title: String(p.title).slice(0, 200), body: String(p.body) };
  } catch (err) {
    console.error("section translation failed:", err);
    return null;
  }
}

